import { describe, expect, it } from "vitest";
import { retryAfterDeadline } from "@/lib/gmail";
import { estimateSeconds } from "@/lib/progress";

const now = Date.parse("2026-10-14T10:00:00Z");
const error = (headers: unknown) => ({ response: { headers } });

describe("Gmail Retry-After", () => {
  it("accepts delta seconds from Headers and case-insensitive objects", () => {
    expect(
      retryAfterDeadline(error(new Headers({ "Retry-After": "300" })), now),
    ).toBe(now + 300000);
    expect(retryAfterDeadline(error({ "Retry-After": " 120 " }), now)).toBe(
      now + 120000,
    );
    expect(retryAfterDeadline(error({ "retry-after": 240 }), now)).toBe(
      now + 240000,
    );
  });
  it.each([
    "Wed, 14 Oct 2026 10:10:00 GMT",
    "Wednesday, 14-Oct-26 10:10:00 GMT",
    "Wed Oct 14 10:10:00 2026",
  ])("accepts HTTP dates: %s", (value) => {
    expect(retryAfterDeadline(error({ "retry-after": value }), now)).toBe(
      now + 600000,
    );
  });
  it.each([
    "",
    "invalid",
    "Wed 2027",
    "-10",
    "1.5",
    "Infinity",
    "1e3",
    "999999999999999999999",
    "Wed, 14 Oct 2026 09:00:00 GMT",
    "0",
    [],
    null,
  ])("ignores invalid or expired values: %j", (value) => {
    expect(retryAfterDeadline(error({ "retry-after": value }), now)).toBeNull();
  });
  it("tolerates missing error metadata", () => {
    expect(retryAfterDeadline(null, now)).toBeNull();
    expect(retryAfterDeadline({}, now)).toBeNull();
  });
});

describe("queue processing estimates", () => {
  it.each([
    [0, 0],
    [1, 5],
    [10, 95],
  ])("estimates %i recipients without an initial delay", (count, seconds) => {
    expect(estimateSeconds(count, null, now)).toBe(seconds);
  });
  it("includes account throttling and safely ignores malformed persisted dates", () => {
    expect(estimateSeconds(10, new Date(now + 240000).toISOString(), now)).toBe(
      335,
    );
    expect(estimateSeconds(1, new Date(now + 600000).toISOString(), now)).toBe(
      605,
    );
    expect(estimateSeconds(0, new Date(now + 240000).toISOString(), now)).toBe(
      0,
    );
    expect(estimateSeconds(10, "invalid", now)).toBe(95);
  });
});
